class TransactionsV2List extends ConsumerStatefulWidget {
  const TransactionsV2List({
    super.key,
    required this.walletId,
    this.asSliver = false,
  });

  final String walletId;

  /// Render as slivers instead of a self-contained scrollable.
  ///
  /// The mobile wallet view scrolls the hero and this list as ONE page, so
  /// the list cannot own a scrollable of its own there. Desktop still uses
  /// the box form, where the list is the only thing scrolling.
  final bool asSliver;

  @override
  ConsumerState<TransactionsV2List> createState() => _TransactionsV2ListState();
}

class _TransactionsV2ListState extends ConsumerState<TransactionsV2List> {
  bool _hasLoaded = false;
  List<TransactionV2> _transactions = [];
  // Cached, already-sorted+processed view of [_transactions]. Recomputed only
  // when the underlying data changes (initial load / db watch), never per
  // build — avoids re-querying + reprocessing the whole list on every rebuild
  // (e.g. when returning from a transaction details page).
  List<Object> _txns = [];

  late final StreamSubscription<List<TransactionV2>> _subscription;
  late final Query<TransactionV2> _query;
  late final CryptoCurrency coin;

  BorderRadius get _borderRadiusFirst {
    return BorderRadius.only(
      topLeft: Radius.circular(Constants.size.circularBorderRadius),
      topRight: Radius.circular(Constants.size.circularBorderRadius),
    );
  }

  BorderRadius get _borderRadiusLast {
    return BorderRadius.only(
      bottomLeft: Radius.circular(Constants.size.circularBorderRadius),
      bottomRight: Radius.circular(Constants.size.circularBorderRadius),
    );
  }

  List<Object> _processData(List<TransactionV2> transactions) {
    if (ref.read(pWallets).getWallet(widget.walletId) is! CashFusionInterface) {
      return transactions;
    }

    final List<Object> processed = [];

    List<TransactionV2> fusions = [];

    for (int i = 0; i < transactions.length; i++) {
      final tx = transactions[i];

      if (tx.subType == TransactionSubType.cashFusion) {
        if (fusions.isNotEmpty) {
          final prevTime = DateTime.fromMillisecondsSinceEpoch(
            fusions.last.timestamp * 1000,
          );
          final thisTime = DateTime.fromMillisecondsSinceEpoch(
            tx.timestamp * 1000,
          );

          if (prevTime.difference(thisTime).inMinutes > 30) {
            processed.add(FusionTxGroup(fusions));
            fusions = [tx];
            continue;
          }
        }

        fusions.add(tx);
      }

      if (i + 1 < transactions.length) {
        final nextTx = transactions[i + 1];
        if (nextTx.subType != TransactionSubType.cashFusion &&
            fusions.isNotEmpty) {
          processed.add(FusionTxGroup(fusions));
          fusions = [];
        }
      }

      if (tx.subType != TransactionSubType.cashFusion) {
        processed.add(tx);
      }
    }

    return processed;
  }

  /// Redesign: rows carry only their time; the date moves into section
  /// headers ("TODAY", "31 AUG") interleaved into the list as Strings.
  /// The list is already sorted newest-first, so one pass suffices.
  List<Object> _withDateHeaders(List<Object> items) {
    final out = <Object>[];
    String? last;
    for (final item in items) {
      final ts = item is TransactionV2
          ? item.timestamp
          : (item as FusionTxGroup).transactions.first.timestamp;
      final label = _dayLabel(ts);
      if (label != last) {
        out.add(label);
        last = label;
      }
      out.add(item);
    }
    return out;
  }

  String _dayLabel(int timestamp) {
    final d = DateTime.fromMillisecondsSinceEpoch(timestamp * 1000);
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final day = DateTime(d.year, d.month, d.day);
    if (day == today) return "TODAY";
    if (day == today.subtract(const Duration(days: 1))) return "YESTERDAY";
    final base = "${d.day} ${Constants.monthMapShort[d.month]}".toUpperCase();
    // The year only where it is not this year — "31 AUG" needs no 2026.
    return d.year == now.year ? base : "$base ${d.year}";
  }

  void _rebuildData() {
    _transactions.sort((a, b) {
      final compare = b.timestamp.compareTo(a.timestamp);
      if (compare == 0) {
        return b.id.compareTo(a.id);
      }
      return compare;
    });
    _txns = _withDateHeaders(_processData(_transactions));
  }

  /// The list with a truncation notice on front, when the sync recorded one.
  ///
  /// A shortened list must say so. Showing the most recent thousand of a pool
  /// address's history as though it were everything would be a claim we cannot
  /// support.
  ///
  /// Built here rather than in [_rebuildData] because that only runs when the
  /// transaction query fires, and the sync records the count afterwards. Read
  /// there, the very first sync of a big address showed a short list with no
  /// explanation, which is the exact thing this notice exists to prevent.
  /// [pWalletInfo] watches the record, so it lands as soon as it is written.
  _TruncationNotice? _truncationNotice(WalletInfo info) {
    final total = info.otherData[WalletInfoKeys.historyTruncatedTotal] as int?;
    if (total != null && total > _transactions.length) {
      return _TruncationNotice(total, _transactions.length);
    }
    return null;
  }

  /// The non-sliver (desktop) list, which still carries the notice inline
  /// because there is no grouped card there for it to sit outside of.
  List<Object> _withTruncationNotice(WalletInfo info) {
    final notice = _truncationNotice(info);
    return notice == null ? _txns : [notice, ..._txns];
  }

  @override
  void initState() {
    coin = ref.read(pWallets).getWallet(widget.walletId).info.coin;
    _query = ref
        .read(mainDBProvider)
        .isar
        .transactionV2s
        .buildQuery<TransactionV2>(
          whereClauses: [
            IndexWhereClause.equalTo(
              indexName: 'walletId',
              value: [widget.walletId],
            ),
          ],
          filter: ref
              .read(pWallets)
              .getWallet(widget.walletId)
              .transactionFilterOperation,
          sortBy: [const SortProperty(property: "timestamp", sort: Sort.desc)],
        );

    // Initial load once (synchronous), then rely on the db watch for updates.
    _transactions = _query.findAllSync();
    _rebuildData();
    _hasLoaded = true;

    _subscription = _query.watch().listen((event) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          setState(() {
            _transactions = event;
            _rebuildData();
          });
        }
      });
    });

    super.initState();
  }

  @override
  void dispose() {
    _subscription.cancel();
    super.dispose();
  }

  /// One row of [txns]. Shared by the box and sliver paths so the two cannot
  /// drift apart.
  Widget _itemAt(List<Object> txns, int index) {
    BorderRadius? radius;
    bool shouldWrap = false;
    if (txns.length == 1) {
      radius = BorderRadius.circular(Constants.size.circularBorderRadius);
    } else if (index == txns.length - 1) {
      radius = _borderRadiusLast;
      shouldWrap = true;
    } else if (index == 0) {
      radius = _borderRadiusFirst;
    }

    final tx = txns[index];
    if (tx is String) {
      return _DateHeader(label: tx);
    }
    if (tx is _TruncationNotice) {
      return _TruncationBanner(total: tx.total, shown: tx.shown);
    }
    // In sliver mode the whole list lives inside one grouped card, so a row
    // must not draw its own fill or corners.
    final grouped = widget.asSliver;
    if (shouldWrap) {
      return Column(
        children: [
          TxListItem(
            tx: tx,
            coin: coin,
            radius: grouped ? null : radius,
            grouped: grouped,
          ),
          const SizedBox(height: WalletView.navBarHeight + 14),
        ],
      );
    }
    return TxListItem(
      tx: tx,
      coin: coin,
      radius: grouped ? null : radius,
      grouped: grouped,
    );
  }

  @override
  Widget build(BuildContext context) {
    if (!_hasLoaded) {
      if (widget.asSliver) {
        return const SliverToBoxAdapter(
          child: Padding(
            padding: EdgeInsets.symmetric(vertical: 60),
            child: Center(child: LoadingIndicator(height: 50, width: 50)),
          ),
        );
      }
      return const Column(
        children: [
          Spacer(),
          Center(child: LoadingIndicator(height: 50, width: 50)),
          Spacer(flex: 4),
        ],
      );
    }
    if (_txns.isEmpty) {
      return widget.asSliver
          ? const SliverToBoxAdapter(child: NoTransActionsFound())
          : const NoTransActionsFound();
    }
    final info = ref.watch(pWalletInfo(widget.walletId));

    if (widget.asSliver) {
      // The notice is its own card ABOVE the list's card, not the list's first
      // row. As a row it rendered inside the grouped card and drew its own box
      // there, so the two read as one card stacked on another. It is also not
      // a transaction, and the card below is a list of transactions.
      //
      // No RefreshIndicator and no physics here: the page that owns this
      // sliver owns the gesture, so pulling anywhere on the screen refreshes,
      // including over the hero.
      final notice = _truncationNotice(info);
      final colors = Theme.of(context).extension<StackColors>()!;

      return SliverMainAxisGroup(
        slivers: [
          if (notice != null)
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.only(bottom: kTxNoticeGapBelow),
                child: _TruncationBanner(
                  total: notice.total,
                  shown: notice.shown,
                ),
              ),
            ),
          // The list owns its card now. It used to be decorated by the wallet
          // view, which is why the notice could not be lifted out of it.
          DecoratedSliver(
            decoration: BoxDecoration(
              color: colors.popupBG,
              borderRadius: BorderRadius.circular(20),
            ),
            sliver: SliverList(
              delegate: SliverChildBuilderDelegate(
                (context, index) => _itemAt(_txns, index),
                childCount: _txns.length,
              ),
            ),
          ),
        ],
      );
    }

    final txns = _withTruncationNotice(info);

    return RefreshIndicator(
      onRefresh: () async {
        await ref.read(pWallets).getWallet(widget.walletId).refresh();
      },
      child: Util.isDesktop
          ? PaginatedListView(
              // Desktop keeps its paginated flat list; headers are a
              // mobile treatment and pagination would orphan them.
              items: txns.where((e) => e is! String).toList(),
              itemBuilder: (context, tx, position) {
                final radius = switch (position) {
                  PageItemPosition.first => _borderRadiusFirst,
                  PageItemPosition.last => _borderRadiusLast,
                  PageItemPosition.solo => BorderRadius.circular(
                    Constants.size.circularBorderRadius,
                  ),
                  PageItemPosition.somewhere => null,
                };

                return TxListItem(tx: tx, coin: coin, radius: radius);
              },
            )
          : ListView.builder(
              padding: const EdgeInsets.only(bottom: 92),
              itemCount: txns.length,
              itemBuilder: (context, index) => _itemAt(txns, index),
            ),
    );
  }
}

/// A day-section header row: "TODAY", "YESTERDAY", "31 AUG", "5 JAN 2025".
class _DateHeader extends StatelessWidget {
  const _DateHeader({required this.label});

  final String label;

  @override
  Widget build(BuildContext context) {
    return Padding(
      // Left inset matches the rows this header labels. It used to be 4
      // against their 16, so the date hung out to the left of the column it
      // belongs to. Top gap larger than the bottom one, so the header binds to
      // the rows below rather than reading as a footer for the day above.
      padding: const EdgeInsets.only(
        left: kTxCardInset,
        right: kTxCardInset,
        top: kTxHeaderGapAbove,
        bottom: kTxHeaderGapBelow,
      ),
      child: Align(
        alignment: Alignment.centerLeft,
        child: Text(
          label,
          style: TextStyle(
            fontSize: 11,
            fontWeight: FontWeight.w600,
            letterSpacing: 1.0,
            color: Theme.of(context).extension<StackColors>()!.textSubtitle1,
          ),
        ),
      ),
    );
  }
}

/// Marker for the list: this address has more history than was synced.
class _TruncationNotice {
  const _TruncationNotice(this.total, this.shown);
  final int total;
  final int shown;
}

/// Says plainly that the list below is partial, and that the balance is not.
///
/// Exchange and pool addresses run to tens of thousands of transactions, which
/// cannot be walked in one sync. The balance stays exact because it is derived
/// from unspent outputs rather than from this list, and saying both halves out
/// loud is the point: a short list with no explanation reads as a wrong list.
class _TruncationBanner extends StatelessWidget {
  const _TruncationBanner({required this.total, required this.shown});

  final int total;
  final int shown;

  /// 45308 -> "45,308". Grouping is what makes these two numbers comparable
  /// at a glance, which is the only reason the banner prints them.
  static String _grouped(int n) {
    final s = n.toString();
    final out = StringBuffer();
    for (int i = 0; i < s.length; i++) {
      if (i > 0 && (s.length - i) % 3 == 0) out.write(",");
      out.write(s[i]);
    }
    return out.toString();
  }

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).extension<StackColors>()!;
    // No margin: this is a card in its own right now, and whoever places it
    // owns the gap to the transaction card below. It keeps the hairline so it
    // still reads as a note rather than as the first row of that list.
    return Container(
      padding: const EdgeInsets.symmetric(
        horizontal: kTxCardInset,
        vertical: 12,
      ),
      decoration: BoxDecoration(
        color: colors.popupBG,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: colors.textSubtitle1.withOpacity(0.15),
          width: 1,
        ),
      ),
      child: Row(
        children: [
          Icon(Icons.info_outline, size: 18, color: colors.textSubtitle1),
          const SizedBox(width: 10),
          Expanded(
            child: Text(
              goTr(
                context,
                "Showing {0} of about {1} transactions. The balance is exact.",
                [_grouped(shown), _grouped(total)],
              ),
              style: TextStyle(fontSize: 12, color: colors.textSubtitle1),
            ),
          ),
        ],
      ),
    );
  }
}
